import{_ as t,o,c as d,ax as a}from"./chunks/framework.Bnt0oLax.js";const n="/docs/assets/connector-detail-code-view.CRoZPw2a.png",m=JSON.parse('{"title":"Code Mode","description":"Code Mode — the JSON representation of a connector, its key-to-form-field mapping, and how the platform validates the JSON on save","frontmatter":{"description":"Code Mode — the JSON representation of a connector, its key-to-form-field mapping, and how the platform validates the JSON on save"},"headers":[],"relativePath":"connectors/code-mode.md","filePath":"connectors/code-mode.md"}'),r={name:"connectors/code-mode.md"};function i(c,e,s,h,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/connectors/code-mode.md for this page in Markdown format</div><h1 id="code-mode" tabindex="-1">Code Mode <a class="header-anchor" href="#code-mode" aria-label="Permalink to &quot;Code Mode&quot;">​</a></h1><p>Code Mode is an alternative to the form-based connector editor. Instead of filling in fields one by one, you define the entire connector as a single JSON object. Use Code Mode when you want to copy configurations between environments, share connector setups with teammates, or manage connectors as code.</p><p>Use the <strong>form editor</strong> for day-to-day setup. Switch to <strong>Code Mode</strong> when you need to bulk-edit fields, paste a configuration from another environment, or version-control the full connector definition. Switching between the form editor and Code Mode is non-destructive — both views reflect the same connector definition and changes in either view are preserved.</p><p>Toggle Code Mode in the connector editor to switch between the visual form and the JSON view:</p><p><img src="'+n+'" alt="Code Mode Interface" data-zoomable="true"></p><h2 id="json-field-reference" tabindex="-1">JSON field reference <a class="header-anchor" href="#json-field-reference" aria-label="Permalink to &quot;JSON field reference&quot;">​</a></h2><p>The JSON object in Code Mode maps directly to the fields in the form editor. For a description of each field, see <a href="./configuration.html">Configuration</a>.</p><table tabindex="0"><thead><tr><th>JSON key</th><th>Form field</th><th>Notes</th></tr></thead><tbody><tr><td><code>name</code></td><td>Connection Name</td><td>Required</td></tr><tr><td><code>url</code></td><td>Endpoint URL</td><td>Required; supports Jinja2</td></tr><tr><td><code>method</code></td><td>HTTP Method</td><td><code>GET</code>, <code>POST</code>, <code>PUT</code>, <code>PATCH</code>, <code>DELETE</code>, <code>HEAD</code>, <code>OPTIONS</code></td></tr><tr><td><code>headers</code></td><td>Headers</td><td>Array of <code>{key, value, overridable}</code> objects</td></tr><tr><td><code>query_parameters</code></td><td>Query Parameters</td><td>Array of <code>{key, value, overridable}</code> objects</td></tr><tr><td><code>path_parameters</code></td><td>Path Parameters</td><td>Array of <code>{key, value?, overridable?}</code> objects. Each <code>key</code> must match a <code>{{ pathParams.X }}</code> reference in <code>url</code>. See <a href="./dynamic-url-paths.html">Dynamic URL Paths</a>.</td></tr><tr><td><code>authentication</code></td><td>Authentication Type</td><td>Object with <code>type</code> and <code>config</code></td></tr><tr><td><code>request_body</code></td><td>Payload Template</td><td>Jinja2 template string</td></tr><tr><td><code>response_body</code></td><td>Response Body</td><td>Jinja2 template for response transformation</td></tr><tr><td><code>response_content_type</code></td><td>Response Content-Type</td><td>Content-Type override for the response</td></tr></tbody></table><h3 id="authentication-object" tabindex="-1">Authentication object <a class="header-anchor" href="#authentication-object" aria-label="Permalink to &quot;Authentication object&quot;">​</a></h3><p>The <code>authentication</code> field takes an object with a <code>type</code> string and a <code>config</code> object whose keys depend on the type. For the exact JSON structure and fields of every supported type, see <a href="./authentication.html#authentication-object">Authentication object</a>.</p><h2 id="validation-on-save" tabindex="-1">Validation on save <a class="header-anchor" href="#validation-on-save" aria-label="Permalink to &quot;Validation on save&quot;">​</a></h2><p>When you save in Code Mode, the platform validates the JSON and all field values. If the JSON is not valid, an error appears with the line and column number. If a field value is invalid (for example, an unsupported HTTP method), a field-level error appears next to that field. Fix the errors and save again.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./configuration.html">Configuration</a> — Full list of connector fields and their requirements</li><li><a href="./authentication.html">Authentication</a> — Authentication type options and JSON structure</li><li><a href="./template-variables.html">Template Variables</a> — Jinja2 syntax for URLs, headers, and payload bodies</li></ul>',15)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
